22	// diffOpts holds the resolved options for `birdseye diff`.
23	type diffOpts struct {
24		Semantic bool
25		Plain    bool
26		CacheDir string
27	}
28	
29	const maxArchiveBytes = 50 << 20 // 50 MiB safety cap on uncompressed size
30	
31	func newDiffCmd(g *GlobalFlags) *cobra.Command {
32		o := &diffOpts{}
33		c := &cobra.Command{
34			Use:   "diff [module] [versionA] [versionB]",
35			Short: "Diff two versions of a Crow module",
36			Long: "Diff two versions of a module hosted in Crow.\n\n" +
37				"If module/versions are omitted, the interactive TUI launches\n" +
38				"(see picker task). With --plain, prints unified diff to stdout.",
39			Args:          cobra.MaximumNArgs(3),
40			SilenceUsage:  true,
41			SilenceErrors: true,
42			RunE: func(cmd *cobra.Command, args []string) error {
43				return runDiff(cmd.Context(), cmd, args, g, o)
44			},
45		}
46		c.Flags().BoolVar(&o.Semantic, "semantic", false, "include HCL-aware semantic diff alongside textual")
47		c.Flags().BoolVar(&o.Plain, "plain", false, "force plain (non-TUI) output")
48		c.Flags().BoolVar(&o.Plain, "no-tui", false, "alias for --plain")
49		c.Flags().StringVar(&o.CacheDir, "cache-dir", defaultCacheDir(), "module tarball cache directory")
50		return c
51	}
52	
53	func defaultCacheDir() string {
54		if home, err := os.UserCacheDir(); err == nil {
55			return filepath.Join(home, "birdseye")
56		}
57		return ".birdseye-cache"
58	}
59	
60	func newHTTPClient(d time.Duration) *http.Client {
61		return &http.Client{Timeout: d}
62	}
63	
64	func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
65		parts := strings.Split(s, "/")
66		if len(parts) != 3 {
67			return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
68		}
69		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
70		if err := id.Validate(); err != nil {
71			return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
72		}
73		return id, nil
74	}
75	
76	func runDiff(ctx context.Context, cmd *cobra.Command, args []string, g *GlobalFlags, o *diffOpts) error {
77		if len(args) == 0 {
78			// Interactive flow lives in Task 15; for now fall through to error.
79			return fmt.Errorf("%w: interactive mode not yet implemented; provide <module> <versionA> <versionB>", ErrUsage)
80		}
81		if len(args) != 3 {
82			return fmt.Errorf("%w: diff requires <module> <versionA> <versionB>", ErrUsage)
83		}
84		id, err := parseModuleAddress(args[0])
85		if err != nil {
86			return err
87		}
88		if err := api.ValidateVersion(args[1]); err != nil {
89			return fmt.Errorf("%w: %v", ErrUsage, err)
90		}
91		if err := api.ValidateVersion(args[2]); err != nil {
92			return fmt.Errorf("%w: %v", ErrUsage, err)
93		}
94		modA := api.Module{ModuleIdentifier: id, Version: args[1]}
95		modB := api.Module{ModuleIdentifier: id, Version: args[2]}
96	
97		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
98		cache, err := registry.NewDiskCache(o.CacheDir)
99		if err != nil {
100			return fmt.Errorf("cache init: %w", err)
101		}
102		reg := registry.New(cli, cache)
103	
104		aBytes, bBytes, err := reg.FetchPair(ctx, modA, modB)
105		if err != nil {
106			return err
107		}
108	
109		modAExtracted, err := archive.Extract(aBytes, maxArchiveBytes)
110		if err != nil {
111			return fmt.Errorf("%w: %v", ErrArchive, err)
112		}
113		modBExtracted, err := archive.Extract(bBytes, maxArchiveBytes)
114		if err != nil {
115			return fmt.Errorf("%w: %v", ErrArchive, err)
116		}
117	
118		result := diff.Result{Files: diff.Textual(modAExtracted, modBExtracted)}
119		// Semantic mode wired in Task 17.
120		// TUI mode wired in Task 13.
121	
122		return renderPlain(cmd.OutOrStdout(), result)
123	}
124	
125	// renderPlain writes the diff result to w in unified-diff format.
126	// "no differences" is emitted when there are zero files in the result.
127	func renderPlain(w io.Writer, r diff.Result) error {
128		if len(r.Files) == 0 {
129			_, err := fmt.Fprintln(w, "no differences")
130			return err
131		}
132		for i, fd := range r.Files {
133			if i > 0 {
134				_, _ = fmt.Fprintln(w)
135			}
136			_, _ = fmt.Fprintf(w, "=== %s (%s) +%d -%d\n", fd.Path, fd.Status, fd.Adds, fd.Dels)
137			_, _ = fmt.Fprint(w, fd.Unified)
138		}
139		return nil
140	}
